const base = "http://[address]:18082";
// v1
const v1 = await (await fetch(base + "/v1/disbursements")).json();
// v2 full export via cursor pagination, dedupe keep-first
let url = base + "/v2/disbursements";
let items = [];
let drained = false, pages = 0;
while (!drained) {
  const r = await (await fetch(url)).json();
  items.push(...r.disbursements);
  drained = r.drained;
  url = base + "/v2/disbursements?cursor=" + encodeURIComponent(r.cursor);
  pages++;
}
const v2 = [];
const seen = new Set();
for (const d of items) { if (!seen.has(d.id)) { seen.add(d.id); v2.push(d); } }
// compare
const byId1 = new Map(v1.disbursements.map(d => [d.id, d]));
const diffs = [];
for (const d of v2) {
  const o = byId1.get(d.id);
  if (!o) { diffs.push({id: d.id, kind: "only-v2"}); continue; }
  for (const k of Object.keys(d)) {
    if (JSON.stringify(d[k]) !== JSON.stringify(o[k])) diffs.push({id: d.id, key: k, v2: d[k], v1: o[k]});
  }
  for (const k of Object.keys(o)) if (!(k in d)) diffs.push({id: d.id, kind: "key-only-v1", key: k});
}
return {v1count: v1.disbursements.length, v2count: v2.length, rawv2: items.length, pages, diffs: diffs.slice(0, 30), diffCount: diffs.length};

