import json,urllib.request,urllib.parse
base='http://[address]:18082'
v1=json.load(urllib.request.urlopen(base+'/v1/disbursements'))['disbursements']
items=[];url=base+'/v2/disbursements';drained=False
while not drained:
 p=json.load(urllib.request.urlopen(url));items+=p['disbursements'];drained=p['drained'];url=base+'/v2/disbursements?'+urllib.parse.urlencode({'cursor':p['cursor']})
v2=[];seen=set()
for d in items:
 if d['id'] not in seen: seen.add(d['id']);v2.append(d)
m1={d['id']:d for d in v1}
diffs=[]
for d in v2:
 o=m1.get(d['id'])
 if o is None: diffs.append(('only-v2',d['id']));continue
 for k in set(d)|set(o):
  if k not in d: diffs.append((d['id'],k,'only-v2'))
  elif k not in o: diffs.append((d['id'],k,'only-v1'))
  elif d[k]!=o[k]: diffs.append((d['id'],k,d[k],o[k]))
print('v1',len(v1),'v2',len(v2),'raw',len(items),'pages ok')
print('diffs',len(diffs))
for x in diffs[:30]: print(x)

